/* From Uiverse.io by Shoh2008 - Tags: card */
@keyframes fadeInScale {
  0% {
    opacity: 0;
    transform: scale(0) translateY(50%);
  }

  90% {
    transform: scale(1.05);
  }

  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.__UIV_SCOPE__ .container {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .card {
  position: relative;
  width: 20em;
  background-color: #292929;
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ .card:hover {
  box-shadow: 0 10px 20px 10px rgba(black, .2);
}

.__UIV_SCOPE__ .card__link {
  display: block;
  padding: 1em;
  text-decoration: none;
}

.__UIV_SCOPE__ .card__icon {
  position: absolute;
  width: 4em;
  height: 4em;
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ .card:hover .card__icon {
  opacity: 0;
  transform: scale(0);
}

.__UIV_SCOPE__ .card__media {
  padding: 2em 0;
}

.__UIV_SCOPE__ .card__media	svg path {
  opacity: 0;
  transition: all .3s ease-in-out;
  transform-origin: center center;
}

.__UIV_SCOPE__ .card:hover svg path {
  animation: fadeInScale .3s ease-in-out forwards;
}

.__UIV_SCOPE__ .card:hover 	svg path:nth-child(2) {
  animation-delay: .1s;
}

.__UIV_SCOPE__ .card:hover 	svg path:nth-child(3) {
  animation-delay: .2s;
}

.__UIV_SCOPE__ .card__header {
  position: relative;
}

.__UIV_SCOPE__ .card__header-title {
  margin: 0 0 .25em;
  color: white;
}

.__UIV_SCOPE__ .card__header-meta {
  margin: 0;
  color: #999;
}

.__UIV_SCOPE__ .card__header-icon {
  opacity: 0;
  position: absolute;
  right: 0;
  top: 50%;
  margin-top: -1em;
  transform: translateX(-20%);
  width: 2em;
  height: 2em;
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ .card:hover .card__header-icon {
  opacity: 1;
  transform: translateX(0);
}
